import React, { useState } from 'react';
import styled from 'styled-components';

const ChatbotContainer = styled.div`
  position: fixed;
  bottom: 20px;
  right: 20px;
  width: 300px;
  max-height: 400px;
  border: 1px solid #ddd;
  border-radius: 10px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  background: #fff;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  z-index: 1000;
`;

const ChatbotHeader = styled.div`
  background: #007bff;
  color: white;
  padding: 10px;
  text-align: center;
  font-weight: bold;
  cursor: pointer;
`;

const ChatWindow = styled.div`
  flex: 1;
  padding: 10px;
  overflow-y: auto;
  font-size: 0.9rem;
  color: #333;
`;

const ChatInputContainer = styled.div`
  display: flex;
  padding: 10px;
  border-top: 1px solid #ddd;
`;

const ChatInput = styled.input`
  flex: 1;
  padding: 8px;
  border: 1px solid #ddd;
  border-radius: 5px;
  font-size: 1rem;
`;

const SendButton = styled.button`
  padding: 8px 15px;
  margin-left: 10px;
  border: none;
  background-color: #007bff;
  color: white;
  border-radius: 5px;
  cursor: pointer;

  &:hover {
    background-color: #0056b3;
  }
`;

const Chatbot = () => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [isOpen, setIsOpen] = useState(true);

  const predefinedResponses = {
    hello: "Hi there! How can I help you?",
    help: "Sure! I can assist with your questions about our site.",
    signup: "To sign up, click the 'Sign Up' button at the top of the page!",
    default: "I'm not sure about that. Try asking something else!",
  };

  const handleSendMessage = () => {
    if (input.trim() === '') return;

    const userMessage = { sender: 'user', text: input };
    const botMessage = {
      sender: 'bot',
      text:
        predefinedResponses[input.toLowerCase()] || predefinedResponses.default,
    };

    setMessages([...messages, userMessage, botMessage]);
    setInput('');
  };

  const toggleChatbot = () => {
    setIsOpen(!isOpen);
  };

  return (
    <ChatbotContainer>
      <ChatbotHeader onClick={toggleChatbot}>
        {isOpen ? 'Chat with us!' : 'Open Chat'}
      </ChatbotHeader>
      {isOpen && (
        <>
          <ChatWindow>
            {messages.map((msg, index) => (
              <p
                key={index}
                style={{
                  textAlign: msg.sender === 'user' ? 'right' : 'left',
                  margin: '5px 0',
                }}
              >
                <strong>{msg.sender === 'user' ? 'You: ' : 'Bot: '}</strong>
                {msg.text}
              </p>
            ))}
          </ChatWindow>
          <ChatInputContainer>
            <ChatInput
              type="text"
              placeholder="Type your message..."
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
            />
            <SendButton onClick={handleSendMessage}>Send</SendButton>
          </ChatInputContainer>
        </>
      )}
    </ChatbotContainer>
  );
};

export default Chatbot;
